"""Lexical import evidence and runtime-state annotation classification."""
from .common import *

def annotation_checks(m,stages,add,extra_inputs):
 from_rule=A(K('import_from_statement'),F('module_name',P('MODULE')),F('name',O(A(K('dotted_name'),P('IMPORTED')),A(K('aliased_import'),F('name',P('IMPORTED')),F('alias',P('ALIAS'))))))
 direct_rule=A(K('import_statement'),F('name',O(A(K('dotted_name'),P('IMPORTED')),A(K('aliased_import'),F('name',P('IMPORTED')),F('alias',P('ALIAS'))))))
 extra_inputs.update({
  'from_imports':E(from_rule,{'module':'capture.MODULE','name':'capture.IMPORTED','alias':'capture.ALIAS'},each='IMPORTED'),
  'direct_imports':E(direct_rule,{'name':'capture.IMPORTED','alias':'capture.ALIAS'},each='IMPORTED'),
 })
 quoted_atom=O(A(K('identifier'),N(I(K('attribute'),'neighbor')),{'capture':'ATOM'}),A(K('attribute'),N(I(K('attribute'),'neighbor')),{'capture':'ATOM'}))
 quoted=A(O(K('string'),K('concatenated_string')),I(A(K('assignment'),P('ANN')),field='type'),{'parse':{'grammar':'annotation','has':{**quoted_atom,'stopBy':'end'}}})
 extra_inputs['quoted_atoms']=E(quoted,{'ann_start':'capture.ANN.startByte','ann_end':'capture.ANN.endByte','atom':'capture.ATOM.text'},each='ATOM')
 stages.extend([
 S('scopes',"SELECT n.*,CASE WHEN n.kind='module' THEN NULL ELSE coalesce(parent.fn,(SELECT id FROM nodes root WHERE root.__path=n.__path AND root.kind='module' LIMIT 1)) END AS enclosing FROM nodes n LEFT JOIN ownership parent ON parent.__path=n.__path AND parent.id=n.edge_parent WHERE n.kind IN ('module','class_definition','function_definition')",('__path','id')),
 S('scope_owners',"SELECT n.__path,n.id,coalesce(CASE WHEN cls.__start>=fn.__start AND cls.__end<=fn.__end OR fn.id IS NULL THEN cls.id ELSE fn.id END,(SELECT id FROM nodes root WHERE root.__path=n.__path AND root.kind='module' LIMIT 1)) AS scope FROM nodes n JOIN ownership own ON own.__path=n.__path AND own.id=n.id LEFT JOIN nodes fn ON fn.__path=own.__path AND fn.id=own.fn LEFT JOIN nodes cls ON cls.__path=own.__path AND cls.id=own.cls",('__path','id'),('__path','scope')),
 S('scope_chain',"WITH RECURSIVE chain(__path,scope,ancestor,depth) AS (SELECT __path,id,id,0 FROM scopes UNION ALL SELECT c.__path,c.scope,s.enclosing,c.depth+1 FROM chain c JOIN scopes s ON s.__path=c.__path AND s.id=c.ancestor WHERE s.enclosing IS NOT NULL) SELECT * FROM chain",('__path','scope','ancestor'),('__path','scope','depth')),
 S('scope_imports',"""SELECT i.__path,o.scope,coalesce(i.alias,i.name) AS name,i.module||'.'||i.name AS origin FROM from_imports i JOIN nodes n ON n.__path=i.__path AND n.__start=i.__start AND n.__end=i.__end AND n.kind='import_from_statement' JOIN scope_owners o ON o.__path=n.__path AND o.id=n.id
 UNION SELECT i.__path,o.scope,coalesce(i.alias,rx_extract(i.name,'^[^.]+',0)),CASE WHEN i.alias IS NULL THEN rx_extract(i.name,'^[^.]+',0) ELSE i.name END FROM direct_imports i JOIN nodes n ON n.__path=i.__path AND n.__start=i.__start AND n.__end=i.__end AND n.kind='import_statement' JOIN scope_owners o ON o.__path=n.__path AND o.id=n.id""",('__path','scope','name')),
 S('scope_shadows',"""WITH bindings AS MATERIALIZED (SELECT *,CASE WHEN kind='delete_statement' THEN id WHEN kind='named_expression' THEN name_kind||':'||name_start||':'||name_end ELSE left_kind||':'||left_start||':'||left_end END AS target_root FROM nodes WHERE kind IN ('assignment','augmented_assignment','delete_statement','for_statement','for_in_clause','named_expression')), declarations AS MATERIALIZED (SELECT * FROM nodes WHERE kind IN ('global_statement','nonlocal_statement')) SELECT DISTINCT n.__path,o.scope,name.text AS name FROM bindings n CROSS JOIN scope_owners o ON o.__path=n.__path AND o.id=n.id CROSS JOIN descendants d ON d.__path=n.__path AND d.root=n.target_root CROSS JOIN py_names name ON name.__path=d.__path AND name.id=d.node
 UNION SELECT p.__path,p.fn,p.name FROM parameters p
 UNION SELECT n.__path,o.scope,n.name_source FROM nodes n JOIN scope_owners o ON o.__path=n.__path AND o.id=n.parent WHERE n.kind IN ('class_definition','function_definition')
 UNION SELECT s.__path,s.id,name.text FROM declarations n CROSS JOIN scopes s ON n.__path=s.__path AND n.__start>=s.__start AND n.__end<=s.__end JOIN nodes name ON name.__path=n.__path AND name.parent=n.id AND name.kind='identifier' WHERE (s.kind='module' AND n.kind='global_statement') OR (s.kind='function_definition' AND n.kind='nonlocal_statement')""",('__path','scope','name')),
 S('annotations',"SELECT n.*,o.scope,s.kind='function_definition' AS function_local FROM assignments n JOIN scope_owners o ON o.__path=n.__path AND o.id=n.id JOIN scopes s ON s.__path=o.__path AND s.id=o.scope WHERE n.type_start IS NOT NULL AND n.target_kind='identifier'",('__path','id'),('__path','scope')),
 S('annotation_atoms',"""SELECT a.__path,a.id AS annotation,a.scope,n.id AS atom_id,n.__start AS atom_start,n.__end AS atom_end,n.text AS atom FROM annotations a JOIN descendants d ON d.__path=a.__path AND d.root=a.type_kind||':'||a.type_start||':'||a.type_end JOIN nodes n ON n.__path=d.__path AND n.id=d.node WHERE n.kind='identifier' AND n.parent_kind!='attribute'
 UNION SELECT a.__path,a.id,a.scope,n.id,n.__start,n.__end,CASE WHEN rx_matches(n.text,'^[A-Za-z_]\\w*(?:\\s*\\.\\s*[A-Za-z_]\\w*)*$') THEN rx_replace(n.text,'\\s+','') ELSE n.attr END FROM annotations a JOIN descendants d ON d.__path=a.__path AND d.root=a.type_kind||':'||a.type_start||':'||a.type_end JOIN attributes n ON n.__path=d.__path AND n.id=d.node WHERE n.parent_kind!='attribute' OR NOT rx_matches(n.text,'^[A-Za-z_]\\w*(?:\\s*\\.\\s*[A-Za-z_]\\w*)*$')
 UNION SELECT a.__path,a.id,a.scope,'quoted:'||q.__start||':'||q.atom,q.__start,q.__end,q.atom FROM quoted_atoms q JOIN annotations a ON a.__path=q.__path AND a.__start=q.ann_start AND a.__end=q.ann_end""",('__path','annotation'),('__path','scope','atom')),
 S('atom_imports',"""SELECT a.*,i.origin,c.depth,NOT EXISTS(SELECT 1 FROM scope_chain shadow_chain JOIN scope_shadows shadow ON shadow.__path=shadow_chain.__path AND shadow.scope=shadow_chain.ancestor AND shadow.name=i.name WHERE shadow_chain.__path=a.__path AND shadow_chain.scope=a.scope AND shadow_chain.depth<=c.depth) AS unshadowed FROM annotation_atoms a JOIN scope_chain c ON c.__path=a.__path AND c.scope=a.scope JOIN scope_imports i ON i.__path=c.__path AND i.scope=c.ancestor AND i.name=rx_extract(a.atom,'^[A-Za-z_]\\w*',0) WHERE NOT EXISTS(SELECT 1 FROM scope_chain near JOIN scope_imports local ON local.__path=near.__path AND local.scope=near.ancestor AND local.name=i.name WHERE near.__path=a.__path AND near.scope=a.scope AND near.depth<c.depth)""",('__path','annotation','atom_id')),
 S('resolved_atoms',"""SELECT a.__path,a.annotation,a.atom_id,a.atom_start,a.atom_end,a.atom,i.origin||substr(a.atom,length(rx_extract(a.atom,'^[A-Za-z_]\\w*',0))+1) AS origin,i.unshadowed AND (SELECT count(DISTINCT x.origin) FROM atom_imports x WHERE x.__path=i.__path AND x.annotation=i.annotation AND x.atom_id=i.atom_id)=1 AS trusted FROM annotation_atoms a JOIN atom_imports i ON i.__path=a.__path AND i.annotation=a.annotation AND i.atom_id=a.atom_id
 UNION SELECT a.__path,a.annotation,a.atom_id,a.atom_start,a.atom_end,a.atom,a.atom,0 FROM annotation_atoms a WHERE NOT EXISTS(SELECT 1 FROM atom_imports i WHERE i.__path=a.__path AND i.annotation=a.annotation AND i.atom_id=a.atom_id)""",('__path','annotation','atom_id')),
 S('ignored_annotation_metadata',"""SELECT DISTINCT a.__path,a.annotation,a.atom_id FROM resolved_atoms a JOIN annotations field ON field.__path=a.__path AND field.id=a.annotation JOIN nodes generic ON generic.__path=a.__path AND generic.kind='generic_type' AND generic.__start>=field.type_start AND generic.__end<=field.type_end
 JOIN nodes base ON base.__path=generic.__path AND base.parent=generic.id AND base.ordinal=0 JOIN resolved_atoms imported ON imported.__path=base.__path AND imported.atom_id=base.id AND imported.annotation=field.id AND imported.trusted AND imported.origin IN ('typing.Literal','typing_extensions.Literal','typing.Annotated','typing_extensions.Annotated')
 JOIN nodes params ON params.__path=generic.__path AND params.parent=generic.id AND params.kind='type_parameter' JOIN nodes arg ON arg.__path=params.__path AND arg.parent=params.id
 WHERE a.atom_start>=arg.__start AND a.atom_end<=arg.__end AND (imported.origin IN ('typing.Literal','typing_extensions.Literal') OR arg.ordinal>0)""",('__path','annotation','atom_id')),
 ])
 nottests="NOT rx_matches(p.__path,'(?:^|/)tests(?:/|$)')"
 add('_check_serverplan_runtime_state_ingress',50,'annotations',nottests+' AND n.target_text IN '+literals(m.SERVERPLAN_RUNTIME_OWNER_FIELD_NAMES),identity="'owner:'||n.id")
 add('_check_serverplan_runtime_state_ingress',50,'annotations',nottests+" AND NOT n.function_local AND rx_matches(n.target_text,"+q('|'.join(re.escape(v) for v in sorted(m.SERVERPLAN_RUNTIME_SERVICE_NAME_PARTS))+r'|bundle|runtime')+')',identity="'field:'||n.id")
 add('_check_serverplan_runtime_state_ingress',50,'annotations',nottests+" AND EXISTS(SELECT 1 FROM resolved_atoms a WHERE a.__path=n.__path AND a.annotation=n.id AND rx_matches(a.origin,'(?:^|\\.)Callable(?:\\.|$)') AND NOT EXISTS(SELECT 1 FROM ignored_annotation_metadata ignored WHERE ignored.__path=a.__path AND ignored.annotation=a.annotation AND ignored.atom_id=a.atom_id))",identity="'callable:'||n.id")
 add('_check_serverplan_runtime_state_ingress',50,'annotations',nottests+" AND EXISTS(SELECT 1 FROM resolved_atoms a WHERE a.__path=n.__path AND a.annotation=n.id AND NOT (a.trusted AND a.origin IN "+literals(m._CONNECTION_ID_SCALAR_EXPORTS)+") AND rx_matches(a.origin,"+q('|'.join(re.escape(v) for v in sorted(m.SERVERPLAN_RUNTIME_SERVICE_NAME_PARTS)))+") AND NOT EXISTS(SELECT 1 FROM ignored_annotation_metadata ignored WHERE ignored.__path=a.__path AND ignored.annotation=a.annotation AND ignored.atom_id=a.atom_id))",identity="'service:'||n.id")
 add('_check_serverplan_runtime_state_ingress',50,'assignments',nottests+" AND n.type_start IS NULL AND n.target_kind='identifier' AND (instr(n.target_text,'UNWRAP')>0 OR instr(n.target_text,'OWNER')>0) AND n.expr_kind IN ('tuple','list','set') AND EXISTS(SELECT 1 FROM nodes item JOIN strings literal ON literal.__path=item.__path AND literal.__start=item.__start AND literal.__end=item.__end WHERE item.__path=n.__path AND item.parent=n.value AND literal.value IN "+literals(m.SERVERPLAN_RUNTIME_OWNER_FIELD_NAMES)+')',identity="'unwrap:'||n.id")
 add('_check_serverplan_runtime_state_ingress',50,'attributes',nottests+" AND n.attr='renewable_capability_bundle'")
 add('_check_serverplan_runtime_state_ingress',50,'calls',nottests+" AND n.callee='runtime_builder_post_op'",identity='k.keyword',join='JOIN keywords k ON k.__path=n.__path AND k.call=n.id AND k.name IN '+literals(m.SERVERPLAN_RUNTIME_BUILDER_KWARGS))
